# Kreator kont i kluczy aplikacji na Androida (issue #117, spec #116). Prowadzi przez wszystko, czego aplikacja
# potrzebuje poza kodem: D-U-N-S i konto organizacji w Play Console, domenę w Search Console, projekt Firebase
# (google-services.json i FIREBASE_SERVICE_ACCOUNT na Vercelu), klucz uploadowy, JDK i Android SDK, a na końcu
# aplikację w Play Console z Play App Signing. Weryfikacja organizacji trwa dni, więc kreator można uruchamiać
# wiele razy: zrobione etapy pomija, a wartości jawne pamięta w .env.android.
#
#   scripts/android-konta.sh

cd "$(dirname "$0")/.."
ENV_FILE=.env.android
PACKAGE=pl.narzedziownikgp.app
MOBILE=mobile/android
GOOGLE_SERVICES=$MOBILE/app/google-services.json
KEYSTORE_PROPERTIES=$MOBILE/keystore.properties
AAB=$MOBILE/app/build/outputs/bundle/release/app-release.aab
PLAY=https://play.google.com/console

# ok "tekst" potwierdza zrobiony krok.
ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# skip_if_done "pytanie" pozwala pominąć etap zrobiony przy poprzednim uruchomieniu.
skip_if_done() {
  if confirm "$1 Pominąć ten etap?"; then ok "pomijam"; return 0; fi
  return 1
}

# ask_file VAR "pytanie" DOMYŚLNA pyta o ścieżkę pliku; Enter bierze domyślną.
ask_file() {
  local var="$1" prompt="$2" default="$3" input
  if [[ -n "$default" ]]; then
    printf '  %s%s%s %s[Enter: %s]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$default" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  input="${input:-$default}"
  printf -v "$var" '%s' "${input/#\~/$HOME}"
}

# newest_download "wzorzec" wypisuje najnowszy pasujący plik w ~/Downloads (podpowiedź do ask_file).
newest_download() {
  local f
  f=$(ls -t "$HOME"/Downloads/$1 2>/dev/null | head -n1) || true
  printf '%s' "$f"
}

# to_clipboard "opis" WARTOŚĆ kładzie wartość do schowka, żeby nie wypisywać jej na ekran.
to_clipboard() {
  if command -v pbcopy >/dev/null 2>&1; then printf '%s' "$2" | pbcopy
  elif command -v wl-copy >/dev/null 2>&1; then printf '%s' "$2" | wl-copy
  elif command -v xclip >/dev/null 2>&1; then printf '%s' "$2" | xclip -selection clipboard
  else warn "brak schowka; $1 musisz przepisać z innego miejsca"; return 1; fi
  ok "w schowku: $1"
}

# google_services_project PLIK sprawdza google-services.json i wypisuje project_id projektu Firebase.
google_services_project() {
  node -e '
    const [file, pkg] = process.argv.slice(1);
    const json = JSON.parse(require("fs").readFileSync(file, "utf8"));
    const packages = (json.client ?? []).map((c) => c.client_info?.android_client_info?.package_name);
    if (!packages.includes(pkg)) {
      console.error(`w pliku nie ma aplikacji ${pkg} (są: ${packages.join(", ") || "żadne"})`);
      process.exit(1);
    }
    console.log(json.project_info.project_id);
  ' "$1" "$PACKAGE"
}

# service_account_json PLIK [PROJEKT] sprawdza klucz konta serwisowego i wypisuje go w jednej linii.
service_account_json() {
  node -e '
    const [file, project] = process.argv.slice(1);
    const json = JSON.parse(require("fs").readFileSync(file, "utf8"));
    if (json.type !== "service_account" || !json.project_id || !json.client_email || !json.private_key) {
      console.error("to nie jest klucz konta serwisowego (brak type=service_account, project_id, client_email albo private_key)");
      process.exit(1);
    }
    if (project && json.project_id !== project) {
      console.error(`klucz jest z projektu ${json.project_id}, a google-services.json z ${project}`);
      process.exit(1);
    }
    process.stdout.write(JSON.stringify(json));
  ' "$1" "${2:-}"
}

# jdk21 wypisuje katalog JDK 21: zainstalowanego w systemie albo dołączonego do Android Studio.
jdk21() {
  local jbr="/Applications/Android Studio.app/Contents/jbr/Contents/Home"
  /usr/libexec/java_home -v 21 2>/dev/null && return
  grep -q '^JAVA_VERSION="21\.' "$jbr/release" 2>/dev/null && printf '%s\n' "$jbr"
}

# cert_sha256 polecenie… wypisuje odcisk SHA-256 certyfikatu z wyjścia keytool.
cert_sha256() { { "$@" 2>/dev/null || true; } | sed -nE '/^[[:space:]]*SHA256: /{s///p;q;}'; }

JAVA21=""
DUNS_NUMBER=$(_existing DUNS_NUMBER || true)
FIREBASE_PROJECT_ID=$(_existing FIREBASE_PROJECT_ID || true)
PLAY_VERIFIED=0
AAB_OK=0
UPLOAD_SHA256=""

TOTAL_STAGES=10

banner "NarzędziownikGP na Androida: konta i klucze (#117)"

stage "JDK 21 i Android SDK"
say "Buildy aplikacji idą z tego Maca. Gradle 8.14 potrzebuje JDK 21 (na JDK 26 się nie uruchomi)."
until JAVA21=$(jdk21) && [[ -n "$JAVA21" ]]; do
  warn "Nie ma JDK 21."
  step "Zainstaluj Temurin 21: brew install --cask temurin@21"
  open_url "https://adoptium.net/temurin/releases/?version=21&os=mac"
  pause "Enter, gdy zainstalowane."
done
ok "JDK 21: $JAVA21"
SDK="${ANDROID_HOME:-$HOME/Library/Android/sdk}"
until [[ -d "$SDK/platforms/android-36" ]] && compgen -G "$SDK/build-tools/36*" >/dev/null; do
  warn "W $SDK nie ma platformy android-36 albo build-tools 36."
  step "Android Studio → Settings → Android SDK: zaznacz Android 16 (API 36) i w SDK Tools Build-Tools 36."
  step "Albo bez Android Studio: sdkmanager \"platforms;android-36\" \"build-tools;36.0.0\"."
  open_url "https://developer.android.com/studio"
  ask_file SDK "Katalog Android SDK:" "$SDK"
done
ok "Android SDK: $SDK"
LOCAL_PROPERTIES=$MOBILE/local.properties
if ! grep -qxF "sdk.dir=$SDK" "$LOCAL_PROPERTIES" 2>/dev/null; then
  { grep -v '^sdk\.dir=' "$LOCAL_PROPERTIES" 2>/dev/null || true; printf 'sdk.dir=%s\n' "$SDK"; } > "$LOCAL_PROPERTIES.tmp"
  mv "$LOCAL_PROPERTIES.tmp" "$LOCAL_PROPERTIES"
  ok "zapisano sdk.dir → $LOCAL_PROPERTIES"
fi
current_java=$(java -version 2>&1 | head -n1 || true)
if [[ "$current_java" != *'"21.'* ]]; then
  note "Domyślna java to ${current_java:-brak}. Gradle uruchamiaj z JDK 21:"
  note "    JAVA_HOME=\"$JAVA21\" ./gradlew …"
fi
pause "Enter, aby przejść dalej."

stage "Numer D-U-N-S firmy"
say "Konto organizacji w Play Console wymaga numeru D-U-N-S (9 cyfr, Dun & Bradstreet)."
say "Nadanie numeru trwa do 30 dni roboczych, więc to pierwszy krok. Firebase i klucz (etapy 5–9) nie czekają na niego."
if [[ "$DUNS_NUMBER" =~ ^[0-9]{9}$ ]]; then
  note "Zapisany numer: $DUNS_NUMBER"
else
  open_url "https://support.google.com/googleplay/android-developer/answer/13628312"
  step "Sprawdź, czy GP Engineering ma już numer (wyszukiwarka D&B):"
  open_url "https://www.dnb.com/duns-number/lookup.html"
  step "Jeśli nie ma, złóż wniosek o darmowy numer. Nazwa i adres dokładnie jak w CEIDG/KRS:"
  open_url "https://www.dnb.com/duns/get-a-duns.html"
  note "Google porównuje dane z D&B z danymi w Play Console; różnica w adresie blokuje weryfikację."
  ask DUNS_NUMBER "Numer D-U-N-S (Enter bez numeru, jeśli jeszcze czekasz):"
  DUNS_NUMBER="${DUNS_NUMBER//[- ]/}"
  if [[ "$DUNS_NUMBER" =~ ^[0-9]{9}$ ]]; then
    write_env DUNS_NUMBER "$DUNS_NUMBER"
  else
    DUNS_NUMBER=""
    SKIPPED+=("D-U-N-S: gdy przyjdzie numer, uruchom kreator ponownie (etapy 3 i 10)")
    warn "Bez numeru pomijam konto Play Console. Reszta działa już teraz."
  fi
fi
pause "Enter, aby przejść dalej."

stage "Konto organizacji w Play Console"
if skip_if_done "Konto organizacji GP Engineering w Play Console jest już założone i zweryfikowane?"; then
  PLAY_VERIFIED=1
elif [[ -z "$DUNS_NUMBER" ]]; then
  warn "Pomijam: brak numeru D-U-N-S."
else
  open_url "$PLAY/signup"
  step "Zaloguj się firmowym kontem Google GP Engineering, nie prywatnym. Tego samego konta użyj w etapach 4 i 5."
  step "Typ konta: organizacja (Organization)."
  step "Numer D-U-N-S: $DUNS_NUMBER. Google pobierze z D&B nazwę i adres firmy, sprawdź, że się zgadzają."
  step "Witryna: https://narzedziownikgp.pl. E-mail i telefon kontaktowy firmy (Google je sprawdza, e-mail widać w sklepie)."
  step "Opłata rejestracyjna: jednorazowo 25 USD, kartą firmową."
  step "Weryfikacja tożsamości organizacji: dokumenty, o które poprosi Play Console. Trwa kilka dni."
  note "Nazwy pól w panelu Google mogą się różnić. Idź za kolejnością kreatora Google."
  if confirm "Weryfikacja organizacji jest już zakończona?"; then
    PLAY_VERIFIED=1
  else
    SKIPPED+=("Play Console: po zakończeniu weryfikacji organizacji uruchom kreator ponownie (etap 10)")
    note "Dalsze etapy nie czekają na weryfikację, oprócz etapu 10."
    pause "Enter, aby przejść dalej."
  fi
fi

stage "Domena w Search Console"
say "Weryfikacja deweloperów Androida sprawdza przez Search Console, że organizacja ma domenę narzedziownikgp.pl."
if ! skip_if_done "Domena narzedziownikgp.pl jest już zweryfikowana w Search Console na koncie z Play Console?"; then
  TXT=$(dig +short TXT narzedziownikgp.pl 2>/dev/null | grep google-site-verification || true)
  [[ -n "$TXT" ]] && note "W DNS jest już rekord: $TXT"
  open_url "https://search.google.com/search-console/welcome"
  step "Zaloguj się kontem Google z Play Console."
  step "Jeśli usługa narzedziownikgp.pl jest na liście i masz w niej uprawnienia właściciela, wystarczy."
  step "Inaczej: Domena → narzedziownikgp.pl → skopiuj rekord TXT google-site-verification=…"
  if confirm "Search Console podał rekord TXT do dodania?"; then
    until [[ "${SITE_VERIFICATION:-}" == google-site-verification=?* ]]; do ask SITE_VERIFICATION "Rekord TXT:"; done
    if [[ "$TXT" == *"$SITE_VERIFICATION"* ]]; then
      note "Ten rekord już jest w DNS. Kliknij Zweryfikuj."
    else
      say "DNS narzedziownikgp.pl jest na Vercelu."
      open_url "https://vercel.com/dashboard/domains"
      step "narzedziownikgp.pl → DNS Records → Add: Name puste, Type TXT, Value z Search Console. Stary rekord zostaw."
      pause "Enter, gdy rekord dodany."
      until dig +short TXT narzedziownikgp.pl 2>/dev/null | grep -F "$SITE_VERIFICATION" >/dev/null; do
        warn "DNS jeszcze nie pokazuje rekordu (zwykle kilka minut)."
        confirm "Sprawdzić jeszcze raz?" || break
      done
      step "W Search Console kliknij Zweryfikuj."
    fi
  fi
  step "Jeśli Play Console przy weryfikacji dewelopera prosi o potwierdzenie witryny, wskaż tę usługę Search Console."
  if ! confirm "Domena jest zweryfikowana w Search Console?"; then
    SKIPPED+=("Search Console: zweryfikuj narzedziownikgp.pl (usługa typu Domena)")
  fi
fi

stage "Projekt Firebase i google-services.json"
say "Aplikacja rejestruje się do powiadomień FCM w projekcie Firebase wskazanym przez google-services.json."
existing_project=""
[[ -f "$GOOGLE_SERVICES" ]] && existing_project=$(google_services_project "$GOOGLE_SERVICES" 2>/dev/null || true)
if [[ -n "$existing_project" ]] && skip_if_done "W $GOOGLE_SERVICES jest już projekt $existing_project."; then
  FIREBASE_PROJECT_ID="$existing_project"
else
  open_url "https://console.firebase.google.com/"
  step "Firmowe konto Google (to samo co Play Console)."
  step "Utwórz projekt narzedziownik-gp. Google Analytics wyłącz, bo aplikacja nie zbiera analityki."
  step "W projekcie: Dodaj aplikację → Android. Nazwa pakietu: $PACKAGE, pseudonim: NarzędziownikGP."
  step "SHA-1 nie jest potrzebny. Zarejestruj aplikację → Pobierz google-services.json."
  step "Kroki „dodaj SDK” pomiń: skorupa ma już wtyczkę google-services."
  pause "Enter, gdy plik pobrany."
  while :; do
    ask_file SOURCE "Pobrany google-services.json:" "$(newest_download 'google-services*.json')"
    if [[ ! -f "$SOURCE" ]]; then warn "Nie ma pliku $SOURCE."; continue; fi
    if FIREBASE_PROJECT_ID=$(google_services_project "$SOURCE"); then break; fi
    warn "Ten plik nie pasuje (powyżej powód). Pobierz go z aplikacji Android $PACKAGE."
  done
  if [[ "$SOURCE" -ef "$GOOGLE_SERVICES" ]]; then
    note "Plik już jest na miejscu: $GOOGLE_SERVICES (projekt $FIREBASE_PROJECT_ID)"
  else
    cp "$SOURCE" "$GOOGLE_SERVICES"
    rm -f "$SOURCE"
    ok "przeniesiono $GOOGLE_SERVICES (projekt $FIREBASE_PROJECT_ID)"
  fi
fi
write_env FIREBASE_PROJECT_ID "$FIREBASE_PROJECT_ID"
note "google-services.json nie jest sekretem (wskazuje projekt). Zacommituj go, żeby każdy build go miał."
pause "Enter, aby przejść dalej."

stage "Konto serwisowe Firebase na Vercelu"
say "Serwer wysyła powiadomienia FCM (HTTP v1) kluczem konta serwisowego w FIREBASE_SERVICE_ACCOUNT (Production)."
if ! command -v vercel >/dev/null 2>&1; then
  warn "Brak Vercel CLI (npm i -g vercel)."
  SKIPPED+=("FIREBASE_SERVICE_ACCOUNT: dodaj w Vercel → Settings → Environment Variables (Production, Sensitive)")
  pause "Enter, aby przejść dalej."
else
  force=()
  set_already=0
  if vercel env ls production 2>/dev/null | grep FIREBASE_SERVICE_ACCOUNT >/dev/null; then
    if skip_if_done "FIREBASE_SERVICE_ACCOUNT jest już w zmiennych Production na Vercelu."; then set_already=1; else force=(--force); fi
  fi
  if (( ! set_already )); then
    open_url "https://console.firebase.google.com/project/$FIREBASE_PROJECT_ID/settings/serviceaccounts/adminsdk"
    step "Firebase Admin SDK → Wygeneruj nowy klucz prywatny → Wygeneruj klucz. Pobierze się plik JSON."
    note "To tajny klucz: pozwala wysyłać powiadomienia w imieniu projektu. Nie wysyłaj go mailem ani czatem."
    pause "Enter, gdy plik pobrany."
    while :; do
      ask_file SOURCE "Pobrany klucz konta serwisowego:" "$(newest_download '*firebase-adminsdk*.json')"
      if [[ ! -f "$SOURCE" ]]; then warn "Nie ma pliku $SOURCE."; continue; fi
      if SERVICE_ACCOUNT=$(service_account_json "$SOURCE" "$FIREBASE_PROJECT_ID"); then break; fi
      warn "Ten plik nie pasuje (powyżej powód)."
    done
    if confirm "Zapisać klucz w FIREBASE_SERVICE_ACCOUNT (Production, Sensitive) na Vercelu?"; then
      if printf '%s' "$SERVICE_ACCOUNT" \
          | vercel env add FIREBASE_SERVICE_ACCOUNT production --sensitive ${force[@]+"${force[@]}"}; then
        ok "ustawiono FIREBASE_SERVICE_ACCOUNT na Vercelu (Production)"
      else
        warn "vercel env add nie zadziałało."
        SKIPPED+=("FIREBASE_SERVICE_ACCOUNT: dodaj w Vercel → Environment Variables (Production, Sensitive) cały plik klucza")
      fi
    else
      SKIPPED+=("FIREBASE_SERVICE_ACCOUNT na Vercelu (Production)")
    fi
    unset SERVICE_ACCOUNT
    vercel env ls production 2>/dev/null | grep FIREBASE_SERVICE_ACCOUNT || warn "Nie widzę zmiennej w vercel env ls production."
    note "Vercel ma klucz, a nowy wygenerujesz w Firebase w każdej chwili. Pobranej kopii nie trzymaj na dysku."
    if confirm "Usunąć pobrany klucz $SOURCE?"; then rm -f "$SOURCE"; ok "usunięto"; fi
  fi
  pause "Enter, aby przejść dalej."
fi

stage "Ponowne wdrożenie produkcji"
say "Nowa zmienna działa dopiero w nowym wdrożeniu."
if ! skip_if_done "Produkcja jest już wdrożona po dodaniu FIREBASE_SERVICE_ACCOUNT?"; then
  open_url "https://vercel.com/dashboard"
  step "narzedziownik-gp → Deployments → najnowsze Production (branch main) → ⋯ → Redeploy."
  step "Poczekaj na stan Ready."
  pause "Enter, gdy produkcja jest wdrożona."
fi

stage "Klucz uploadowy"
say "Google trzyma klucz podpisu aplikacji (Play App Signing), a my klucz uploadowy, którym podpisujemy pakiety."
say "Klucz i hasło idą do firmowego menedżera haseł, nie tylko na ten laptop."
KEYSTORE=$(_existing UPLOAD_KEYSTORE || true)
KEYSTORE="${KEYSTORE:-$HOME/narzedziownikgp-upload.jks}"
KEY_ALIAS=upload
# keytool czyta hasło ze zmiennej środowiskowej (-storepass:env), nie z argumentów widocznych w ps.
export KS_PASS=""
if [[ -f "$KEYSTORE_PROPERTIES" ]] && skip_if_done "Jest już $KEYSTORE_PROPERTIES."; then
  KEYSTORE=$(sed -nE 's/^storeFile=//p' "$KEYSTORE_PROPERTIES")
  # Gradle czyta storeFile względem modułu app (file() w app/build.gradle).
  [[ "$KEYSTORE" == /* ]] || KEYSTORE="$MOBILE/app/$KEYSTORE"
  KEY_ALIAS=$(sed -nE 's/^keyAlias=//p' "$KEYSTORE_PROPERTIES")
  KS_PASS=$(sed -nE 's/^storePassword=//p' "$KEYSTORE_PROPERTIES")
else
  if [[ -f "$KEYSTORE" ]] || confirm "Klucz uploadowy jest już w firmowym menedżerze haseł (np. z innego komputera)?"; then
    say "Używam istniejącego klucza; drugiego nie zakładam (Play Console zna tylko jeden)."
    until [[ -f "$KEYSTORE" ]]; do
      step "Zapisz plik .jks z menedżera haseł na dysku."
      ask_file KEYSTORE "Plik klucza:" "$KEYSTORE"
    done
    ask_secret KS_PASS "Hasło klucza z menedżera haseł:"
  else
    KS_PASS=$(openssl rand -hex 20)
    to_clipboard "hasło klucza uploadowego" "$KS_PASS" || printf '  Hasło: %s\n' "$KS_PASS"
    step "Załóż w firmowym menedżerze haseł wpis „NarzędziownikGP: klucz uploadowy Android” i wklej hasło."
    pause "Enter, gdy hasło zapisane."
    keytool -genkeypair -v -keystore "$KEYSTORE" -storetype PKCS12 -alias upload -keyalg RSA -keysize 2048 \
      -validity 10000 -dname "CN=GP Engineering, O=GP Engineering, C=PL" -storepass:env KS_PASS -keypass:env KS_PASS
    to_clipboard "pusty schowek (bez hasła)" "" || true
    step "Dołącz plik $KEYSTORE do tego wpisu w menedżerze haseł. Plik bez hasła i hasło bez pliku są bezużyteczne,"
    step "a zgubiony klucz to procedura resetu u Google i przerwa w wydaniach."
    if ! confirm "Plik i hasło są w menedżerze haseł?"; then
      SKIPPED+=("Klucz uploadowy: dołącz $KEYSTORE i hasło do firmowego menedżera haseł")
    fi
  fi
  until keytool -list -keystore "$KEYSTORE" -alias upload -storepass:env KS_PASS >/dev/null 2>&1; do
    warn "Hasło nie otwiera $KEYSTORE albo nie ma w nim aliasu upload."
    ask_secret KS_PASS "Hasło klucza:"
  done
  (umask 077; printf 'storeFile=%s\nstorePassword=%s\nkeyAlias=upload\nkeyPassword=%s\n' "$KEYSTORE" "$KS_PASS" "$KS_PASS" > "$KEYSTORE_PROPERTIES")
  ok "zapisano $KEYSTORE_PROPERTIES (poza repozytorium)"
  write_env UPLOAD_KEYSTORE "$KEYSTORE"
fi
UPLOAD_SHA256=$(cert_sha256 keytool -list -v -keystore "$KEYSTORE" -alias "$KEY_ALIAS" -storepass:env KS_PASS)
unset KS_PASS
if [[ -n "$UPLOAD_SHA256" ]]; then
  note "Odcisk SHA-256 certyfikatu uploadowego: $UPLOAD_SHA256"
else
  warn "Nie odczytałem certyfikatu z $KEYSTORE (alias $KEY_ALIAS). Sprawdź $KEYSTORE_PROPERTIES."
  SKIPPED+=("Klucz uploadowy: $KEYSTORE_PROPERTIES nie otwiera klucza")
fi
pause "Enter, aby przejść dalej."

stage "Podpisany pakiet AAB"
say "Buduję wydanie tak jak przed każdym wgraniem do Play Console (mobile/README.md), z adresem produkcji."
if confirm "Zbudować podpisany AAB (npx cap sync android, ./gradlew bundleRelease z JDK 21)?"; then
  if (cd mobile && { [[ -d node_modules ]] || npm install; } && env -u CAP_SERVER_URL npx cap sync android \
      && cd android && JAVA_HOME="$JAVA21" ./gradlew bundleRelease); then
    AAB_OK=1
  else
    warn "Build się nie udał (log powyżej)."
    SKIPPED+=("AAB: cd mobile && npx cap sync android && cd android && JAVA_HOME=\"$JAVA21\" ./gradlew bundleRelease")
  fi
else
  SKIPPED+=("AAB: zbuduj według mobile/README.md (Wydanie)")
fi
if (( AAB_OK )); then
  aab_sha256=$(cert_sha256 keytool -printcert -jarfile "$AAB")
  server=$(unzip -p "$AAB" base/assets/capacitor.config.json 2>/dev/null | sed -nE 's/.*"url": *"([^"]*)".*/\1/p' || true)
  if [[ -z "$aab_sha256" ]]; then
    warn "$AAB nie ma podpisu (brak $KEYSTORE_PROPERTIES?). Play Console go nie przyjmie."; AAB_OK=0
  elif [[ "$aab_sha256" != "$UPLOAD_SHA256" ]]; then
    warn "$AAB nie jest podpisany kluczem uploadowym z etapu 8 (podpis $aab_sha256)."; AAB_OK=0
  elif [[ "$server" != "https://narzedziownikgp.pl" ]]; then
    warn "$AAB ładuje ${server:-nieznany adres} zamiast produkcji (sync z CAP_SERVER_URL?)."; AAB_OK=0
  else
    ok "podpisany kluczem uploadowym, ładuje $server: $AAB"
  fi
  (( AAB_OK )) || SKIPPED+=("AAB: przebuduj z kluczem uploadowym i adresem produkcji")
fi
pause "Enter, aby przejść dalej."

stage "Aplikacja w Play Console i Play App Signing"
if (( ! PLAY_VERIFIED )); then
  warn "Pomijam: konto organizacji w Play Console nie jest jeszcze zweryfikowane."
  SKIPPED+=("Aplikacja $PACKAGE w Play Console: po weryfikacji organizacji uruchom kreator ponownie")
  pause "Enter, aby przejść dalej."
elif ! skip_if_done "Aplikacja $PACKAGE jest już w Play Console z Play App Signing?"; then
  open_url "$PLAY"
  step "Wszystkie aplikacje → Utwórz aplikację."
  step "Nazwa: NarzędziownikGP · język domyślny: polski (pl-PL) · Aplikacja · Bezpłatna · deklaracje → Utwórz."
  say "Nazwę pakietu Play Console przypisuje przy pierwszym wgranym AAB i wtedy ustawia Play App Signing."
  (( AAB_OK )) || warn "Nie ma sprawdzonego AAB z etapu 9. Bez niego aplikacja nie dostanie pakietu."
  step "Testowanie → Testy wewnętrzne → Utwórz nową wersję."
  step "Podpisywanie aplikacji: klucz wygenerowany przez Google (Play App Signing)."
  step "Wgraj $AAB i sprawdź, że Play Console pokazuje $PACKAGE, wersję 1 (1.0)."
  step "Zapisz jako wersję roboczą. Nie wysyłaj do sprawdzenia: wydanie i testerzy to #129."
  step "Konfiguracja → Integralność aplikacji → Podpisywanie aplikacji: Play App Signing włączone."
  [[ -n "$UPLOAD_SHA256" ]] && step "Certyfikat klucza przesyłania ma tam odcisk SHA-256: $UPLOAD_SHA256"
  note "Kod wersji 1 jest odtąd zajęty: następny AAB musi mieć versionCode 2 (mobile/android/app/build.gradle)."
  if ! confirm "Aplikacja $PACKAGE jest w Play Console z Play App Signing?"; then
    SKIPPED+=("Aplikacja $PACKAGE w Play Console z Play App Signing")
  fi
fi

finish
say "Zacommituj $GOOGLE_SERVICES, jeśli się zmienił. Na koniec odhacz kryteria w issue #117."
printf '\n'
